vec2 Z;//; = vec2(0.01,.040); // mess about with this

struct mandlbrot{vec2 C; vec2 z;};
#define maxCheck  clamp((0+int(iTime*20.)),0,300)

float manT2(mandlbrot m)
{
    for(int i = 0; i<maxCheck; i++){
        m.z = vec2(pow(abs(m.z.x),2.0)-pow(abs(m.z.y),2.0),2.0*m.z.x*m.z.y)+m.C;
        if(length(m.z)>=40.0){
            return .69 - (float(i)/float(maxCheck));
        }
    }
    return abs(m.z.x)+abs(m.C.y);
}

float manT(mandlbrot m)
{
    for(int i = 0; i<maxCheck; i++){
        m.z = vec2(pow(abs(m.z.x),2.0)-pow(abs(m.z.y),2.0),2.0*m.z.x*m.z.y)+m.C;
        if(length(m.z)>=13.50){
            return log2((iTime+10.))/6. - sqrt((float(i)/float(maxCheck)));
        }
    }
    return (.2102);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){

    vec2 offset = vec2(-0.039+0.005*sin(iTime/4.),-0.6855); // or this
float t= iTime+1.;
    float zoom = (t)*t*60.;
    mandlbrot plane = mandlbrot(fragCoord/zoom-((iResolution.xy/zoom)/11.0)+offset, Z);

    vec3 col = vec3(manT(plane));

    fragColor = vec4(pow(col.r*(1.9+sqrt(t/4.)/12.0),sqrt(t/1.)));
}
